<script>const salesByTap=@json($salesByTap);const updateTemplate=@json(route('surya.outlet-list.update',['idOutlet'=>'__ID__']));const modal=document.getElementById('edit-modal');document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{document.getElementById('modal-outlet').textContent=b.dataset.name+' · '+b.dataset.id;const sf=document.getElementById('edit-sf');sf.innerHTML='<option value="UNMAPPING">UNMAPPING</option>';(salesByTap[b.dataset.tap]||[]).forEach(x=>{const o=document.createElement('option');o.value=x.namasf;o.textContent=x.namasf+' ('+x.idsf+')';sf.appendChild(o)});sf.value=b.dataset.sf||'UNMAPPING';document.getElementById('edit-pjp').value=b.dataset.pjp||'UNMAPPING';document.getElementById('edit-form').action=updateTemplate.replace('__ID__',encodeURIComponent(b.dataset.id));modal.classList.add('open')});document.querySelectorAll('.close').forEach(b=>b.onclick=()=>modal.classList.remove('open'));modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')}</script>
